import React, { useState, useCallback, useMemo, useEffect } from 'react';
import axios from 'axios';
import { Line, Bar } from 'react-chartjs-2';
import { 
  Chart as ChartJS, 
  CategoryScale, 
  LinearScale, 
  PointElement,
  LineElement,
  BarElement, 
  Title, 
  Tooltip, 
  Legend 
} from 'chart.js';
import { 
  Container, 
  Typography, 
  TextField, 
  Button, 
  Paper, 
  Grid, 
  Box, 
  CircularProgress, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  Table, 
  TableBody, 
  TableCell, 
  TableContainer, 
  TableHead, 
  TableRow, 
  List, 
  ListItem, 
  ListItemButton, 
  ListItemText, 
  Divider, 
  Chip, 
  Alert,
  Tabs,
  Tab
} from '@mui/material';
import { ThemeProvider, createTheme } from '@mui/material/styles';

// Register Chart.js components globally
ChartJS.register(
  CategoryScale, 
  LinearScale, 
  PointElement,
  LineElement,
  BarElement, 
  Title, 
  Tooltip, 
  Legend
);

// API configuration
const API_URL = 'http://localhost:8000';
const HISTORY_KEY = 'cos30049-v5-history';

function readSavedHistory() {
  try {
    const saved = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
    return Array.isArray(saved) ? saved : [];
  } catch (err) {
    return [];
  }
}

function writeSavedHistory(items) {
  localStorage.setItem(HISTORY_KEY, JSON.stringify(items));
}

let modelPromise = null;

function loadModel() {
  if (!modelPromise) {
    modelPromise = fetch('data/model.json').then((response) => {
      if (!response.ok) throw new Error('The prediction model could not be loaded.');
      return response.json();
    });
  }
  return modelPromise;
}

function walkTree(tree, values) {
  let node = 0;
  while (tree.left[node] !== -1) {
    const feature = tree.feature[node];
    node = values[feature] <= tree.threshold[node] ? tree.left[node] : tree.right[node];
  }
  return tree.value[node];
}

function predictLocally(model, population, income) {
  const results = [];
  model.categories.forEach((category) => {
    model.fuels.forEach((fuel) => {
      const values = new Array(model.nFeatures).fill(0);
      values[0] = (population - model.mean[0]) / model.scale[0];
      values[1] = (income - model.mean[1]) / model.scale[1];
      values[2 + model.categories.indexOf(category)] = 1;
      values[2 + model.categories.length + model.fuels.indexOf(fuel)] = 1;
      const total = model.trees.reduce((sum, tree) => sum + walkTree(tree, values), 0);
      results.push({ type: category, fuel, number: Math.trunc(total / model.trees.length) });
    });
  });
  return results;
}

// Theme configuration
const theme = createTheme({
  palette: {
    primary: { main: '#1976d2' },
    secondary: { main: '#dc004e' }
  }
});

// Error logging hook
const useErrorLog = () => {
  return useCallback((error, info) => {
    console.error('Error occurred:', error, info);
  }, []);
};

// Main Application Component
export default function App() {
  const errorLog = useErrorLog();
  
  // Navigation tab state ('prediction' or 'historical')
  const [currentTab, setCurrentTab] = useState('prediction');

  // --- PREDICTION PAGE STATES ---
  const [population, setPopulation] = useState('');
  const [income, setIncome] = useState('');
  const [predictions, setPredictions] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Filter states for predictions
  const [selectedType, setSelectedType] = useState('All');
  const [selectedFuel, setSelectedFuel] = useState('All');

  // History states for predictions
  const [history, setHistory] = useState([]);
  const [selectedHistoryId, setSelectedHistoryId] = useState(null);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState('');

  // --- HISTORICAL DATA PAGE STATES ---
  const [historicalData, setHistoricalData] = useState([]);
  const [historicalLoading, setHistoricalLoading] = useState(false);
  const [historicalError, setHistoricalError] = useState('');
  const [histStateFilter, setHistStateFilter] = useState('All');
  const [histCategoryFilter, setHistCategoryFilter] = useState('All');

  // Prediction history stays in this browser.
  const fetchPredictionHistory = async () => {
    setHistoryLoading(true);
    setHistoryError('');
    setHistory(readSavedHistory());
    setHistoryLoading(false);
  };

  const loadHistoricalFile = async () => {
    const response = await fetch('data/historical_dataset.csv');
    if (!response.ok) throw new Error('missing file');
    const text = await response.text();
    const lines = text.trim().split(/\r?\n/);
    const headers = lines.shift().split(',');
    return lines.filter(Boolean).map((line) => {
      const cells = line.split(',');
      const row = {};
      headers.forEach((header, index) => {
        row[header] = cells[index];
      });
      return row;
    });
  };

  // Fetch historical CSV data from backend, then from the zip file.
  const fetchHistoricalData = async () => {
    try {
      setHistoricalLoading(true);
      setHistoricalError('');
      try {
        const response = await axios.get(`${API_URL}/historical-data`, { timeout: 1500 });
        setHistoricalData(response.data.data || []);
      } catch (err) {
        setHistoricalData(await loadHistoricalFile());
        errorLog(err, 'Using the zip historical file');
      }
    } catch (err) {
      setHistoricalError('Unable to load historical CSV data.');
      errorLog(err, 'Error loading historical data');
    } finally {
      setHistoricalLoading(false);
    }
  };

  // Load history and historical data when application starts
  useEffect(() => {
    fetchPredictionHistory();
    fetchHistoricalData();
  }, []);

  // --- PREDICTION LOGIC & MEMOS ---
  const vehicleTypes = useMemo(() => {
    return [...new Set(predictions.map(item => item.type))];
  }, [predictions]);

  const fuelTypes = useMemo(() => {
    return [...new Set(predictions.map(item => item.fuel))];
  }, [predictions]);

  const filteredPredictions = useMemo(() => {
    return predictions.filter(item => {
      const typeMatch = selectedType === 'All' || item.type === selectedType;
      const fuelMatch = selectedFuel === 'All' || item.fuel === selectedFuel;
      return typeMatch && fuelMatch;
    });
  }, [predictions, selectedType, selectedFuel]);

  // Generate chart data dynamically for predictions
  const chartData = useMemo(() => {
    const fuels = [...new Set(filteredPredictions.map(item => item.fuel))];
    const types = [...new Set(filteredPredictions.map(item => item.type))];

    const colors = [
      'rgba(66, 133, 244, 0.8)',
      'rgba(244, 163, 64, 0.8)',
      'rgba(76, 175, 80, 0.8)',
      'rgba(156, 39, 176, 0.8)',
      'rgba(255, 99, 132, 0.8)',
      'rgba(0, 188, 212, 0.8)',
      'rgba(121, 85, 72, 0.8)'
    ];

    const datasets = types.map((type, index) => {
      return {
        label: type,
        data: fuels.map(fuel => {
          const matchingPredictions = filteredPredictions.filter(
            item => item.type === type && item.fuel === fuel
          );
          return matchingPredictions.reduce(
            (total, item) => total + Number(item.number || 0),
            0
          );
        }),
        backgroundColor: colors[index % colors.length],
        borderWidth: 1
      };
    });

    return {
      labels: fuels,
      datasets
    };
  }, [filteredPredictions]);

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        position: 'top',
        title: { display: true, text: 'Vehicle Type' }
      },
      title: { display: true, text: 'Predicted Number of Vehicles by Fuel Type' },
      tooltip: {
        callbacks: {
          label: function(context) {
            return context.dataset.label + ': ' + context.parsed.y.toLocaleString();
          }
        }
      }
    },
    scales: {
      x: { stacked: true, title: { display: true, text: 'Fuel Type' } },
      y: {
        stacked: true,
        beginAtZero: true,
        title: { display: true, text: 'Predicted Number of Vehicles' },
        ticks: { callback: function(value) { return value.toLocaleString(); } }
      }
    }
  };

  const handleResetFilters = () => {
    setSelectedType('All');
    setSelectedFuel('All');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setPredictions([]);
    setSelectedHistoryId(null);
    setSelectedType('All');
    setSelectedFuel('All');

    if (
      !Number.isInteger(Number(population)) ||
      Number(population) <= 1 ||
      !Number.isInteger(Number(income)) ||
      Number(income) < 1
    ) {
      setError(
        'Population must be an integer greater than 1 and income must be an integer greater than or equal to 1.'
      );
      return;
    }

    setLoading(true);

    try {
      let results;
      try {
        const response = await axios.post(`${API_URL}/predict`, {
          population: Number(population),
          income: Number(income)
        }, { timeout: 1500 });
        results = response.data.Predictions;
      } catch (err) {
        results = predictLocally(await loadModel(), Number(population), Number(income));
        errorLog(err, 'Using the saved model in the browser');
      }

      if (!Array.isArray(results)) {
        throw new Error('Invalid prediction data received from backend.');
      }

      const item = {
        id: Date.now(),
        population: Number(population),
        income: Number(income),
        created_at: new Date().toISOString(),
        predictions: results
      };
      const nextHistory = [item, ...readSavedHistory()].slice(0, 20);
      writeSavedHistory(nextHistory);
      setHistory(nextHistory);
      setPredictions(results);
      setSelectedHistoryId(item.id);
    } catch (err) {
      setError(
        err.response?.data?.detail ||
        err.message ||
        'Error predicting vehicles. Please try again.'
      );
      errorLog(err, 'Error predicting vehicles');
    } finally {
      setLoading(false);
    }
  };

  const handleSelectHistory = async (historyId) => {
    try {
      setError('');
      const selected = readSavedHistory().find((item) => item.id === historyId);
      if (!selected) throw new Error('That saved prediction is no longer in this browser.');

      setPopulation(String(selected.population));
      setIncome(String(selected.income));
      setPredictions(selected.predictions || []);
      setSelectedHistoryId(selected.id);
      setSelectedType('All');
      setSelectedFuel('All');
    } catch (err) {
      setError(
        err.response?.data?.detail || 'Unable to load selected prediction.'
      );
      errorLog(err, 'Error loading historical prediction');
    }
  };

  // --- HISTORICAL DATA FILTERS & CHARTS LOGIC ---
  const uniqueStates = useMemo(() => {
    return [...new Set(historicalData.map(i => i.state).filter(Boolean))];
  }, [historicalData]);

  const uniqueCategories = useMemo(() => {
    return [...new Set(historicalData.map(i => i.category).filter(Boolean))];
  }, [historicalData]);

  const filteredHistoricalData = useMemo(() => {
    return historicalData.filter(item => {
      const stateMatch = histStateFilter === 'All' || item.state === histStateFilter;
      const catMatch = histCategoryFilter === 'All' || item.category === histCategoryFilter;
      return stateMatch && catMatch;
    });
  }, [historicalData, histStateFilter, histCategoryFilter]);

  // Line chart data for historical records (Count over Date)
  const historicalLineChartData = useMemo(() => {
    const dateMap = {};
    filteredHistoricalData.forEach(item => {
      const d = item.date;
      if (!d) return;
      if (!dateMap[d]) dateMap[d] = 0;
      dateMap[d] += Number(item.count || 0);
    });

    const sortedDates = Object.keys(dateMap).sort();

    return {
      labels: sortedDates,
      datasets: [
        {
          label: 'Total Count Over Time',
          data: sortedDates.map(d => dateMap[d]),
          borderColor: 'rgb(25, 118, 210)',
          backgroundColor: 'rgba(25, 118, 210, 0.5)',
          tension: 0.1
        }
      ]
    };
  }, [filteredHistoricalData]);

  // Bar chart data for historical records (Count by Category)
  const historicalBarChartData = useMemo(() => {
    const categoryMap = {};
    filteredHistoricalData.forEach(item => {
      const cat = item.category || 'Unknown';
      if (!categoryMap[cat]) categoryMap[cat] = 0;
      categoryMap[cat] += Number(item.count || 0);
    });

    return {
      labels: Object.keys(categoryMap),
      datasets: [
        {
          label: 'Count by Category',
          data: Object.values(categoryMap),
          backgroundColor: 'rgba(220, 0, 78, 0.7)',
        }
      ]
    };
  }, [filteredHistoricalData]);


  // Main UI
  return (
    <ThemeProvider theme={theme}>
      <Container maxWidth="lg">
        <Box sx={{ my: 4 }}>
          
          {/* Main Title */}
          <Typography variant="h3" component="h1" gutterBottom>
            Malaysia Vehicle Dashboard
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Version 5 · the website from the zip
          </Typography>

          {/* Navigation Tabs */}
          <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
            <Tabs value={currentTab} onChange={(e, val) => setCurrentTab(val)}>
              <Tab label="Prediction Page" value="prediction" />
              <Tab label="Historical Data Page" value="historical" />
            </Tabs>
          </Box>

          {/* ================================================= */}
          {/* TAB 1: PREDICTION PAGE                            */}
          {/* ================================================= */}
          {currentTab === 'prediction' && (
            <Box>
              <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                Predict vehicle statistics based on population and income.
              </Typography>

              {/* Prediction Input Form */}
              <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
                <Typography variant="h5" gutterBottom>
                  Prediction Input
                </Typography>
                <form onSubmit={handleSubmit}>
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        type="number"
                        label="Population"
                        variant="outlined"
                        value={population}
                        onChange={(e) => setPopulation(e.target.value)}
                        inputProps={{ min: 2, step: 1 }}
                        required
                      />
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        type="number"
                        label="Mean Income"
                        variant="outlined"
                        value={income}
                        onChange={(e) => setIncome(e.target.value)}
                        inputProps={{ min: 1, step: 1 }}
                        required
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        fullWidth
                        disabled={loading}
                        size="large"
                      >
                        {loading ? (
                          <CircularProgress size={24} color="inherit" />
                        ) : (
                          'Predict Vehicles'
                        )}
                      </Button>
                    </Grid>
                  </Grid>
                </form>
              </Paper>

              {/* Error Message */}
              {error && (
                <Alert severity="error" sx={{ mb: 3 }}>
                  {error}
                </Alert>
              )}

              {/* Prediction History Component */}
              <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
                <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                  <Typography variant="h5">Prediction History</Typography>
                  <Button
                    variant="outlined"
                    size="small"
                    onClick={fetchPredictionHistory}
                    disabled={historyLoading}
                  >
                    Refresh
                  </Button>
                </Box>

                {historyError && (
                  <Alert severity="warning" sx={{ mb: 2 }}>
                    {historyError}
                  </Alert>
                )}

                {historyLoading ? (
                  <Box textAlign="center" sx={{ py: 2 }}>
                    <CircularProgress size={30} />
                  </Box>
                ) : history.length === 0 ? (
                  <Typography color="text.secondary" sx={{ py: 2 }}>
                    No prediction history available.
                  </Typography>
                ) : (
                  <List>
                    {history.map((item) => (
                      <React.Fragment key={item.id}>
                        <ListItem disablePadding>
                          <ListItemButton
                            selected={selectedHistoryId === item.id}
                            onClick={() => handleSelectHistory(item.id)}
                          >
                            <ListItemText
                              primary={`Prediction #${item.id}`}
                              secondary={`Population: ${Number(item.population).toLocaleString()} | Mean Income: ${Number(item.income).toLocaleString()} | ${new Date(item.created_at).toLocaleString()}`}
                            />
                            {selectedHistoryId === item.id && (
                              <Chip label="Selected" color="primary" size="small" />
                            )}
                          </ListItemButton>
                        </ListItem>
                        <Divider />
                      </React.Fragment>
                    ))}
                  </List>
                )}
              </Paper>

              {/* Prediction Results */}
              {predictions.length > 0 && (
                <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
                  <Typography variant="h5" gutterBottom>
                    Vehicle Prediction Results
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Population: {Number(population).toLocaleString()} | Mean Income: {Number(income).toLocaleString()}
                  </Typography>

                  {/* Filters */}
                  <Typography variant="subtitle1" sx={{ mt: 2, mb: 2, fontWeight: 'bold' }}>
                    Filter Predictions
                  </Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <FormControl fullWidth>
                        <InputLabel>Vehicle Type</InputLabel>
                        <Select
                          value={selectedType}
                          label="Vehicle Type"
                          onChange={(e) => setSelectedType(e.target.value)}
                        >
                          <MenuItem value="All">All Vehicle Types</MenuItem>
                          {vehicleTypes.map(type => (
                            <MenuItem key={type} value={type}>
                              {type}
                            </MenuItem>
                          ))}
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <FormControl fullWidth>
                        <InputLabel>Fuel Type</InputLabel>
                        <Select
                          value={selectedFuel}
                          label="Fuel Type"
                          onChange={(e) => setSelectedFuel(e.target.value)}
                        >
                          <MenuItem value="All">All Fuel Types</MenuItem>
                          {fuelTypes.map(fuel => (
                            <MenuItem key={fuel} value={fuel}>
                              {fuel}
                            </MenuItem>
                          ))}
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid item xs={12}>
                      <Button
                        variant="outlined"
                        color="secondary"
                        fullWidth
                        onClick={handleResetFilters}
                      >
                        Reset Filters
                      </Button>
                    </Grid>
                  </Grid>

                  <Box sx={{ mt: 2, mb: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                      Showing {filteredPredictions.length} of {predictions.length} predictions
                    </Typography>
                  </Box>

                  {/* Chart */}
                  {filteredPredictions.length > 0 ? (
                    <Box sx={{ mt: 3 }}>
                      <Bar data={chartData} options={chartOptions} />
                    </Box>
                  ) : (
                    <Typography color="text.secondary" sx={{ mt: 3, textAlign: 'center' }}>
                      No predictions match the selected filters.
                    </Typography>
                  )}

                  {/* Table */}
                  <Box sx={{ mt: 4 }}>
                    <Typography variant="h6" gutterBottom>
                      Prediction Details
                    </Typography>
                    <TableContainer>
                      <Table>
                        <TableHead>
                          <TableRow>
                            <TableCell>Vehicle Type</TableCell>
                            <TableCell>Fuel Type</TableCell>
                            <TableCell align="right">Predicted Number</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {filteredPredictions.map((item, index) => (
                            <TableRow key={`${item.type}-${item.fuel}-${index}`}>
                              <TableCell>{item.type}</TableCell>
                              <TableCell>{item.fuel}</TableCell>
                              <TableCell align="right">
                                {Number(item.number).toLocaleString()}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </Box>
                </Paper>
              )}
            </Box>
          )}

          {/* ================================================= */}
          {/* TAB 2: HISTORICAL DATA PAGE                       */}
          {/* ================================================= */}
          {currentTab === 'historical' && (
            <Box>
              <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                Explore historical vehicle records from the CSV dataset.
              </Typography>

              {historicalError && (
                <Alert severity="warning" sx={{ mb: 2 }}>
                  {historicalError}
                </Alert>
              )}

              {historicalLoading ? (
                <Box textAlign="center" sx={{ py: 4 }}>
                  <CircularProgress />
                </Box>
              ) : (
                <Box>
                  {/* Historical Filters */}
                  <Paper elevation={2} sx={{ p: 2, mb: 3 }}>
                    <Typography variant="subtitle1" gutterBottom fontWeight="bold">
                      Filter Historical Records
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} sm={6}>
                        <FormControl fullWidth size="small">
                          <InputLabel>State</InputLabel>
                          <Select
                            value={histStateFilter}
                            label="State"
                            onChange={(e) => setHistStateFilter(e.target.value)}
                          >
                            <MenuItem value="All">All States</MenuItem>
                            {uniqueStates.map(st => (
                              <MenuItem key={st} value={st}>{st}</MenuItem>
                            ))}
                          </Select>
                        </FormControl>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <FormControl fullWidth size="small">
                          <InputLabel>Category</InputLabel>
                          <Select
                            value={histCategoryFilter}
                            label="Category"
                            onChange={(e) => setHistCategoryFilter(e.target.value)}
                          >
                            <MenuItem value="All">All Categories</MenuItem>
                            {uniqueCategories.map(cat => (
                              <MenuItem key={cat} value={cat}>{cat}</MenuItem>
                            ))}
                          </Select>
                        </FormControl>
                      </Grid>
                    </Grid>
                  </Paper>

                  {/* Charts Grid */}
                  <Grid container spacing={3} sx={{ mb: 4 }}>
                    <Grid item xs={12} md={6}>
                      <Paper elevation={3} sx={{ p: 3 }}>
                        <Typography variant="h6" gutterBottom>
                          Count Trend Over Time
                        </Typography>
                        <Line data={historicalLineChartData} />
                      </Paper>
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <Paper elevation={3} sx={{ p: 3 }}>
                        <Typography variant="h6" gutterBottom>
                          Distribution by Category
                        </Typography>
                        <Bar data={historicalBarChartData} />
                      </Paper>
                    </Grid>
                  </Grid>

                  {/* Historical Data Table */}
                  <Paper elevation={3} sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>
                      Historical Records ({filteredHistoricalData.length} records found)
                    </Typography>
                    <TableContainer sx={{ maxHeight: 400 }}>
                      <Table stickyHeader>
                        <TableHead>
                          <TableRow>
                            <TableCell>Date</TableCell>
                            <TableCell>State</TableCell>
                            <TableCell>Category</TableCell>
                            <TableCell>Fuel</TableCell>
                            <TableCell align="right">Count</TableCell>
                            <TableCell align="right">Income Mean</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {filteredHistoricalData.slice(0, 50).map((row, idx) => (
                            <TableRow key={idx}>
                              <TableCell>{row.date}</TableCell>
                              <TableCell>{row.state}</TableCell>
                              <TableCell>{row.category}</TableCell>
                              <TableCell>{row.fuel}</TableCell>
                              <TableCell align="right">
                                {Number(row.count || 0).toLocaleString()}
                              </TableCell>
                              <TableCell align="right">
                                {Number(row.income_mean || 0).toLocaleString()}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </Paper>
                </Box>
              )}
            </Box>
          )}

        </Box>
      </Container>
    </ThemeProvider>
  );
}